        control(results, 'CLEANUP_REMOVES_LINKS_IN_READ_ONLY_DIRECTORIES', code_ws == 0 and code == 0 and not copy.exists()
                and (outside / 'keep.txt').is_file(), {'workspace': code_ws, 'cleanup': code, 'output': output[-300:]})
